import { readFileSync } from "node:fs";

let config;
try {
  config = JSON.parse(readFileSync("config.json", "utf8"));
} catch {
  config = { exportsDir: "exports", keepDays: 30 };
}

console.log(`exporting into ${config.exportsDir}`);

