import { readFileSync } from "node:fs";

const config = JSON.parse(readFileSync("config.json", "utf8"));

console.log(`importing from ${config.exportsDir}`);

files.scripts/report.mjs:
import { readFileSync, existsSync } from "node:fs";

const config = existsSync("config.json") ? JSON.parse(readFileSync("config.json", "utf8")) : {};

console.log(`reporting on ${config.exportsDir ?? "exports"} (${config.keepDays ?? 30} days)`);
